diagrams.plantuml:
@startuml
class Task {
  +number: int
  +title: str
  +due: date [0..1]
  +done: bool
}
class TaskService {
  +add(title: str, due: date): Task
  +list(): Task[*]
  +complete(number: int): Task
  +delete(number: int): void
}
interface TaskRepository {
  +load(): Task[*]
  +save(tasks: Task[*]): void
}
class JsonTaskRepository {
  +path: str
}
class Cli {
  +run(args: str[*]): int
}
Cli --> TaskService : uses
TaskService --> TaskRepository : stores via
TaskService "1" o-- "0..*" Task : manages
JsonTaskRepository ..|> TaskRepository
@enduml

